const STORAGE_KEY = 'hkdi-seat-manager-mobile-v2';
let seats=[], selectedId=null, zoom=1, mode='select', dragging=null, currentFilter='all';
const layer=document.getElementById('seatLayer'), map=document.getElementById('map'), scroller=document.getElementById('mapScroller');
const bottomSheet=document.getElementById('bottomSheet'), seatForm=document.getElementById('seatForm'), sheetEmpty=document.getElementById('sheetEmpty');
function loadSeats(){const saved=localStorage.getItem(STORAGE_KEY);seats=saved?JSON.parse(saved):PRESET_SEATS;}
function saveSeats(){localStorage.setItem(STORAGE_KEY,JSON.stringify(seats));updateSummary();}
function label(s){return s.guest?s.guest.split(' ')[0].slice(0,8):s.id.replace(/^[LCR]-/,'');}
function visibleByFilter(s){return currentFilter==='all'||(s.category||'empty')===currentFilter;}
function renderSeats(){layer.innerHTML='';seats.forEach(s=>{const el=document.createElement('div');el.className=`seat ${s.category||'empty'} ${s.id===selectedId?'selected':''} ${visibleByFilter(s)?'':'dimmed'}`;el.dataset.id=s.id;el.style.left=s.x+'%';el.style.top=s.y+'%';el.style.transform=`rotate(${s.rot||0}deg)`;el.title=`${s.id}
${s.guest||'Empty'}`;if(s.photo){const img=document.createElement('img');img.src=s.photo;el.appendChild(img);}const span=document.createElement('span');span.className='mini-label';span.textContent=label(s);el.appendChild(span);el.addEventListener('click',e=>{e.stopPropagation();selectSeat(s.id,true);});el.addEventListener('pointerdown',startDrag);layer.appendChild(el);});updateSummary();}
function seat(){return seats.find(s=>s.id===selectedId);}
function selectSeat(id,open=true){selectedId=id;renderSeats();fillSheet();if(open)bottomSheet.classList.add('open');}
function fillSheet(){const s=seat();if(!s){seatForm.classList.add('hidden');sheetEmpty.classList.remove('hidden');return;}sheetEmpty.classList.add('hidden');seatForm.classList.remove('hidden');document.getElementById('seatTitle').textContent=s.id;document.getElementById('seatSub').textContent=(s.guest||'Empty')+(s.company?' · '+s.company:'');document.getElementById('guestName').value=s.guest||'';document.getElementById('company').value=s.company||'';document.getElementById('category').value=s.category||'empty';document.getElementById('remarks').value=s.remarks||'';document.getElementById('photoPreview').innerHTML=s.photo?`<img src="${s.photo}" alt="photo">`:'Photo';}
seatForm.addEventListener('submit',e=>{e.preventDefault();const s=seat();if(!s)return;s.guest=document.getElementById('guestName').value.trim();s.company=document.getElementById('company').value.trim();s.category=document.getElementById('category').value;s.remarks=document.getElementById('remarks').value.trim();saveSeats();renderSeats();fillSheet();});
document.getElementById('photo').addEventListener('change',e=>{const s=seat();const f=e.target.files[0];if(!s||!f)return;const r=new FileReader();r.onload=()=>{s.photo=r.result;saveSeats();renderSeats();fillSheet();};r.readAsDataURL(f);});
document.getElementById('btnCheckIn').onclick=()=>{const s=seat();if(!s)return;s.category='checked';saveSeats();renderSeats();fillSheet();};
document.getElementById('btnClearSeat').onclick=()=>{const s=seat();if(!s)return;Object.assign(s,{guest:'',company:'',remarks:'',photo:'',category:'empty'});saveSeats();renderSeats();fillSheet();};
document.getElementById('btnCloseSheet').onclick=()=>bottomSheet.classList.remove('open');
function setZoom(z,center=false){zoom=Math.max(.35,Math.min(2.4,z));map.style.transform=`scale(${zoom})`;document.getElementById('zoomLabel').textContent=Math.round(zoom*100)+'%';}
document.getElementById('zoomIn').onclick=()=>setZoom(zoom+.12);document.getElementById('zoomOut').onclick=()=>setZoom(zoom-.12);document.getElementById('btnFit').onclick=()=>{const w=scroller.clientWidth-24;setZoom(w/1448);scroller.scrollTo(0,0);};
document.getElementById('modeMove').onclick=()=>{mode=mode==='move'?'select':'move';document.getElementById('modeMove').classList.toggle('active',mode==='move');document.getElementById('modeAdd').classList.remove('active');};
document.getElementById('modeAdd').onclick=()=>{mode=mode==='add'?'select':'add';document.getElementById('modeAdd').classList.toggle('active',mode==='add');document.getElementById('modeMove').classList.remove('active');};
layer.addEventListener('click',e=>{if(mode!=='add')return;const rect=layer.getBoundingClientRect();const x=((e.clientX-rect.left)/rect.width)*100,y=((e.clientY-rect.top)/rect.height)*100;const id=prompt('New seat ID, e.g. TEMP01');if(!id)return;seats.push({id:id.trim(),x:+x.toFixed(4),y:+y.toFixed(4),rot:0,category:'empty',guest:'',company:'',remarks:'',photo:''});selectSeat(id.trim(),true);saveSeats();renderSeats();});
function startDrag(e){if(mode!=='move')return;e.preventDefault();selectSeat(e.currentTarget.dataset.id,false);dragging={seat:seat(),rect:layer.getBoundingClientRect()};e.currentTarget.setPointerCapture(e.pointerId);}
window.addEventListener('pointermove',e=>{if(!dragging)return;const x=((e.clientX-dragging.rect.left)/dragging.rect.width)*100,y=((e.clientY-dragging.rect.top)/dragging.rect.height)*100;dragging.seat.x=Math.max(0,Math.min(100,+x.toFixed(4)));dragging.seat.y=Math.max(0,Math.min(100,+y.toFixed(4)));renderSeats();});
window.addEventListener('pointerup',()=>{if(dragging){saveSeats();dragging=null;}});
// simple pinch zoom
let pinchStart=null;scroller.addEventListener('touchstart',e=>{if(e.touches.length===2){const dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY;pinchStart={dist:Math.hypot(dx,dy),zoom};}},{passive:true});
scroller.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchStart){e.preventDefault();const dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY;setZoom(pinchStart.zoom*(Math.hypot(dx,dy)/pinchStart.dist));}},{passive:false});
scroller.addEventListener('touchend',()=>{pinchStart=null;},{passive:true});

document.querySelectorAll('.quickbar button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.quickbar button').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentFilter=b.dataset.filter;renderSeats();});
function updateSummary(){const c={total:seats.length,empty:0,guest:0,vip:0,vvip:0,vvvip:0,judge:0,checked:0,blocked:0,assigned:0};seats.forEach(s=>{const cat=s.category||'empty';c[cat]=(c[cat]||0)+1;if(cat!=='empty'&&cat!=='blocked')c.assigned++;});document.getElementById('summary').innerHTML=Object.entries(c).map(([k,v])=>`<span>${k}</span><b>${v}</b>`).join('');}
const searchInput=document.getElementById('searchInput'), results=document.getElementById('searchResults');
searchInput.addEventListener('input',()=>{const q=searchInput.value.trim().toLowerCase();if(!q){results.style.display='none';results.innerHTML='';return;}const found=seats.filter(s=>[s.id,s.guest,s.company,s.category,s.remarks].join(' ').toLowerCase().includes(q)).slice(0,50);results.innerHTML=found.map(s=>`<div class="result-item" data-id="${s.id}"><b>${s.id}</b> — ${s.guest||'Empty'}<br><small>${s.company||s.category||''}</small></div>`).join('')||'<div class="result-item">No result</div>';results.style.display='block';results.querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>{selectSeat(el.dataset.id,true);results.style.display='none';document.querySelector(`[data-id="${CSS.escape(el.dataset.id)}"]`)?.scrollIntoView({block:'center',inline:'center'});});});
document.getElementById('btnClearSearch').onclick=()=>{searchInput.value='';results.style.display='none';};
document.getElementById('btnShowStats').onclick=()=>document.getElementById('statsPanel').classList.remove('hidden');document.getElementById('btnCloseStats').onclick=()=>document.getElementById('statsPanel').classList.add('hidden');
document.getElementById('btnExport').onclick=()=>{const blob=new Blob([JSON.stringify(seats,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hkdi-seat-manager-mobile-backup.json';a.click();URL.revokeObjectURL(a.href);};
document.getElementById('importJson').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{seats=JSON.parse(r.result);saveSeats();renderSeats();fillSheet();};r.readAsText(f);});
document.getElementById('btnPrint').onclick=()=>window.print();
loadSeats();renderSeats();setZoom(Math.min(1,(window.innerWidth-24)/1448));fillSheet();
